#!/usr/bin/env python3
"""Builds podcast_script_mobiliteit{,_fr,_de,_lb}.md from build/mobiliteit_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "mobiliteit"
HEAD = {
 "en": ('# Podcast Script — "On the Move for Free – Public Transport and mobiliteit.lu"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « En route gratuitement – Les transports publics et mobiliteit.lu »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Kostenlos unterwegs – Der öffentliche Verkehr und mobiliteit.lu“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Gratis ënnerwee – Den ëffentlechen Transport a mobiliteit.lu“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 10, "de": 12, "lb": 10}   # EN 10:29, FR 10:13, DE 11:42 (28 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources (official only, consulted on 28 November 2026): mobiliteit.lu (a service of the Public Transport Administration, ATP) — home page (journey planner, timetables and lines incl. school buses, Nightbus and city buses, disruptions and works, networks and maps, reduced mobility, fares, app, Leetstell, contact); \"Fares\" (free public transport in the whole country since 1 March 2020, the first country in the world; no ticket for tram, bus or train except 1st class; free travel ends at the border; free 2nd class journeys to and from Athus (B), Audun-le-Tiche (F) and Volmerange-les-Mines (F); 1st class products; RegioZone bus tickets; checks at the latest at the last stop in Luxembourg before the border; sale via the CFL go app, CFL International app, ticket machines and CFL counters; no more mKaart or paper tickets on buses); \"Harmonisation and digitalisation of cross-border and 1st class tickets\" (since 1 January 2026: one RegioZone fare for bus links with the neighbouring countries except the Saarbrücken Express coach, one CFL 1st class subscription sold monthly or yearly, the mKaart no longer valid, help at the CFL sales centres); \"Contact\" (call centre 2465 2465, open every day incl. weekends and public holidays; contact form for suggestions, comments or complaints); video tutorials of the app (real-time departures, line search with delays and works, favourites, personal alerts, school transport tab, My Mix, bike-sharing, feedback button); \"Nightbus\" (night buses run by several communes); terms of use of the app (third-party data: bike sharing, charging stations, car parks and P+R). atp.gouvernement.lu — the Administration (created by the law of 5 February 2021, working since 1 March 2021, under the Ministry of Mobility and Public Works; plans the RGTR with more than 200 lines and the school buses; call centre; Leetstell control centre; Adapto and Mobibus; journey planner; complaints), Adapto, Mobibus. guichet.public.lu — \"Using public transport in Luxembourg\" (free 2nd class domestic travel on the RGTR, CFL, AVL, Luxtram and TICE networks; valid ID card; children under 4 with someone aged at least 12; 1st class paid from age 12; bicycles, pets, assistance dogs, luggage, prams, wheelchairs; owners responsible, nothing may block other travellers), \"Adapto – travel card for people with reduced mobility\" (card; trips booked in advance via the call centre, online or the app; pick-up on the pavement; only within Luxembourg). transports.public.lu — free mobility, tram (Findel – Luxembourg Airport station since 2 March 2025; tram tracks reserved for the tram), journey planner criteria. luxembourg.public.lu and blogcfl.lu (CFL) — bicycles free on trains, subject to space; bike places behind the green doors. vdl.lu — free bus, tram, 2nd class train and funicular; City Night Bus. Durable wording only: no prices, no opening hours, no line or passenger figures beyond \"more than two hundred\" RGTR lines. Accurate as of November 2026.*",
 "fr": "*Sources (officielles uniquement, consultées le 28 novembre 2026) : mobiliteit.lu (un service de l'Administration des transports publics, ATP) — page d'accueil (planifier un trajet, horaires et lignes y compris bus scolaires, Nightbus et City-bus, perturbations et chantiers, réseaux et plans, mobilité réduite, tarifs, application, Leetstell, contact) ; « Tarifs » (gratuité dans tout le pays depuis le 1er mars 2020, premier pays au monde ; pas de billet pour le tram, le bus ou le train sauf en 1re classe ; la gratuité s'arrête à la frontière ; trajets gratuits en 2e classe vers et depuis Athus (B), Audun-le-Tiche (F) et Volmerange-les-Mines (F) ; billets RegioZone ; contrôle au plus tard au dernier arrêt au Luxembourg avant la frontière ; vente via l'application CFL go, l'application CFL International, les distributeurs et les guichets CFL ; fin de la mKaart et des billets papier dans les bus) ; « Harmonisation et digitalisation des titres transfrontaliers et de 1re classe » (depuis le 1er janvier 2026 : un seul tarif RegioZone pour les bus vers les pays voisins, sauf l'autocar Saarbrücken Express ; un abonnement 1re classe CFL au mois ou à l'année ; mKaart plus valable) ; « Contact » (centrale d'appels 2465 2465, ouverte tous les jours ; formulaire de contact) ; tutoriels vidéo de l'application ; « Nightbus » ; conditions d'utilisation de l'application. atp.gouvernement.lu — l'Administration (loi du 5 février 2021, en fonction depuis le 1er mars 2021, ministère de la Mobilité et des Travaux publics ; RGTR avec plus de 200 lignes, bus scolaires, centrale d'appels, centre de contrôle Leetstell, Adapto et Mobibus, planificateur, réclamations). guichet.public.lu — « Circulation dans les transports publics au Luxembourg » (carte d'identité valable ; enfants de moins de 4 ans accompagnés d'une personne d'au moins 12 ans ; 1re classe payante dès 12 ans ; vélos, animaux, chiens d'assistance, bagages, poussettes, fauteuils roulants) ; « Adapto – carte d'accès » (réservation à l'avance via la centrale, en ligne ou l'application ; prise en charge sur le trottoir ; uniquement au Luxembourg). transports.public.lu — gratuité, tram (station Findel – Luxembourg Airport depuis le 2 mars 2025 ; voies réservées au tram), critères du planificateur. luxembourg.public.lu et blogcfl.lu (CFL) — vélos gratuits dans le train, selon la place ; portes vertes. vdl.lu — bus, tram, train 2e classe et funiculaire gratuits ; City Night Bus. Formulations durables uniquement : pas de prix, pas d'horaires d'ouverture, pas de chiffres sauf « plus de deux cents » lignes RGTR. Exact en novembre 2026.*",
 "de": "*Quellen (nur offizielle, abgerufen am 28. November 2026): mobiliteit.lu (ein Dienst der Verwaltung für öffentlichen Verkehr, ATP) — Startseite (Route planen, Fahrpläne und Linien einschließlich Schulbusse, Nightbus und City-Bus, Störungen und Baustellen, Netze und Pläne, eingeschränkte Mobilität, Fahrpreise, App, Leetstell, Kontakt); „Fahrpreise“ (kostenlos im ganzen Land seit dem 1. März 2020, erstes Land der Welt; keine Fahrkarte für Straßenbahn, Bus oder Zug außer 1. Klasse; die kostenlose Fahrt endet an der Grenze; kostenlose Fahrten in der 2. Klasse nach und von Athus (B), Audun-le-Tiche (F) und Volmerange-les-Mines (F); RegioZone-Fahrkarten; Kontrolle spätestens an der letzten Haltestelle in Luxemburg vor der Grenze; Verkauf über die App CFL go, die App CFL International, Automaten und CFL-Schalter; keine mKaart und keine Papierfahrkarten mehr im Bus); „Harmonisierung und Digitalisierung der grenzüberschreitenden und Erste-Klasse-Fahrkarten“ (seit 1. Januar 2026: ein einziger RegioZone-Tarif für Busse in die Nachbarländer außer dem Saarbrücken Express; ein CFL-Abonnement 1. Klasse pro Monat oder Jahr; mKaart nicht mehr gültig); „Kontakt“ (Callcenter 2465 2465, jeden Tag erreichbar; Kontaktformular); Video-Tutorials der App; „Nightbus“; Nutzungsbedingungen der App. atp.gouvernement.lu — die Verwaltung (Gesetz vom 5. Februar 2021, tätig seit 1. März 2021, Ministerium für Mobilität und öffentliche Arbeiten; RGTR mit mehr als 200 Linien, Schulbusse, Callcenter, Leitstelle Leetstell, Adapto und Mobibus, Routenplaner, Beschwerden). guichet.public.lu — „Benutzung der öffentlichen Verkehrsmittel in Luxemburg“ (gültiger Personalausweis; Kinder unter 4 Jahren in Begleitung einer Person ab 12 Jahren; 1. Klasse ab 12 Jahren kostenpflichtig; Fahrräder, Haustiere, Assistenzhunde, Gepäck, Kinderwagen, Rollstühle); „Adapto – Ausweis“ (Buchung im Voraus über das Callcenter, online oder die App; Abholung am Bordstein; nur in Luxemburg). transports.public.lu — kostenlose Mobilität, Straßenbahn (Station Findel – Luxembourg Airport seit 2. März 2025; Schienen nur für die Straßenbahn), Kriterien des Routenplaners. luxembourg.public.lu und blogcfl.lu (CFL) — Fahrräder im Zug kostenlos, je nach Platz; grüne Türen. vdl.lu — Bus, Straßenbahn, Zug 2. Klasse und Standseilbahn kostenlos; City Night Bus. Nur dauerhafte Angaben: keine Preise, keine Öffnungszeiten, keine Zahlen außer „mehr als zweihundert“ RGTR-Linien. Stand: November 2026.*",
 "lb": "*Quellen (nëmmen offiziell, consultéiert de 28. November 2026): mobiliteit.lu (Verwaltung vum ëffentlechen Transport, ATP): Startsäit, Tariffer, Harmoniséierung vun den Ticketen zënter dem 1. Januar 2026, Kontakt, App-Tutorials, Nightbus; atp.gouvernement.lu (Verwaltung, Adapto, Mobibus); guichet.public.lu (Benotzung vum ëffentlechen Transport, Adapto-Kaart); transports.public.lu (Gratis Mobilitéit, Tram); luxembourg.public.lu a blogcfl.lu (Vëloen am Zuch); vdl.lu. Keng Präisser, keng Ëffnungszäiten. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/mobiliteit_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 40, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
